const ESLINT_TS_RULES = [
	...ANGULAR_ESLINT_TS_RULES_DERIVED,
	...ANGULAR_ESLINT_RULES_ADDED.map((entry) => entry.rule),
];

function severities(rules: readonly string[]): Record<string, 'error'> {
	return Object.fromEntries(rules.map((rule) => [rule, 'error' as const]));
}

let cachedEslint: ESLint | undefined;
function makeEslint(): ESLint {
	cachedEslint ??= new ESLint({
		cwd: PACKAGE_ROOT,
		overrideConfigFile: true,
		// Emitted output must not be able to configure the gate that reads it.
		allowInlineConfig: false,
		overrideConfig: [
			{
				files: ['**/*.ts'],
				languageOptions: {
					parser: tsParser as never,
					parserOptions: { ecmaVersion: 'latest', sourceType: 'module' },
				},
				plugins: { '@angular-eslint': ngPlugin as never },
				// The processor is what lets the TEMPLATE rules reach an INLINE
				// template. Without it the four template rules would sit silent on
				// single-file components and the arbiter would be half a gate.
				processor: tplPlugin.processors['extract-inline-html'] as never,
				rules: severities(ESLINT_TS_RULES),
			},
			{
				files: ['**/*.html'],
				languageOptions: { parser: templateParser as never },
				plugins: { '@angular-eslint/template': tplPlugin as never },
				rules: severities(ANGULAR_ESLINT_TEMPLATE_RULES_DERIVED),
			},
		] as never,
	});
	return cachedEslint;
}

/**
 * `eslint:` marks a THIRD-PARTY arbiter, following the qwik, svelte and vue
 * gates. The frameless-owned policies in this file keep their BARE ids: they are
 * not eslint rules at all - they are hand-written walkers over Angular's own
 * template AST and TypeScript's own module AST - so a `frameless/` prefix would
 * imply a plugin that does not exist. The distinction the prefix carries is "who
 * decided this", and here it is carried by presence versus absence of `eslint:`.
 */
function eslintPolicyId(ruleId: string | null | undefined): string {
	return `eslint:${ruleId ?? 'parse'}`;
}

async function eslintViolations(file: string, source: string): Promise<GateViolation[]> {
	const [result] = await makeEslint().lintText(source, {
		filePath: resolve(PACKAGE_ROOT, file),
		warnIgnored: false,
	});
	return (result?.messages ?? []).map((message) =>
		violation(file, eslintPolicyId(message.ruleId), message.message, message.line ?? null),
	);
}

