	{ id: 'template-parse', dossierRef: 'frameless-angular-v1 T002 ruling 4 (both arbiters, compiler first)' },
	{ id: 'whitespace-stable-text', dossierRef: 'frameless-angular-v1 T003 measurement M1' },
