		attributes.push(eventAttribute(event, indent));
	}
	const singleLine = `<${node.tag}${attributes.map((attribute) => ` ${attribute}`).join('')}>`;
	const fits =
		!attributes.some((attribute) => attribute.includes('\n')) &&
		width(indent, singleLine) <= PRINT_WIDTH;
	if (inline && !fits)
		throw new Error(
			`Svelte emitter cannot inline <${node.tag}>: it sits beside text and needs a multi-line start tag`,
		);
	const open = fits
		? singleLine
		: `<${node.tag}\n${attributes.map((attribute) => `${indent}\t${attribute}`).join('\n')}\n${indent}>`;
	const isVoid = VOID_ELEMENTS.has(node.tag);
	if (isVoid) {
		if (node.children.length)
			throw new Error(`Svelte void element <${node.tag}> cannot have children`);
		return prefixIgnores(node, open, context);
	}
	const close = `</${node.tag}>`;
	if (node.children.length === 0) return prefixIgnores(node, open + close, context);
	if (inline || hasTextChild(node.children)) {
		const children = node.children
			.map((child) => renderNode(child, indent, true))
			.join('');
		return prefixIgnores(node, open + children + close, context);
	}
	const chunks = [
		open,
		...node.children.map((child) => renderNode(child, `${indent}\t`, false)),
	];
	const body = joinSiblings(chunks, `${indent}\t`);
	return prefixIgnores(node, appendSibling(body, close, indent), context);
}

/**
 * The sanctioned annotation is emitted INLINE, with no whitespace between it and
 * the element, so it can never introduce a text node at a sibling boundary.
 */
function prefixIgnores(
	node: Extract<TemplateNode, { kind: 'host' }>,
	rendered: string,
	context: EmitContext,
): string {
	if (!node.eventIds.length || !A11Y_EVENT_HOST_TAGS.has(node.tag)) return rendered;
	for (const code of SANCTIONED_SVELTE_IGNORE_CODES) context.suppressed.add(code);
	return `<!-- svelte-ignore ${SANCTIONED_SVELTE_IGNORE_CODES.join(', ')} -->${rendered}`;
}

function renderBranch(
	node: Extract<TemplateNode, { kind: 'branch' }>,
	indent: string,
	inline: boolean,
): string {
	if (node.arms.length < 1 || node.arms.length > 2)
		throw new Error(`Svelte branch ${node.id} requires a then arm and at most one else arm`);
	if (node.arms[0]!.kind !== 'then')
		throw new Error(`Svelte branch ${node.id} must open with a then arm`);
	if (node.arms[1] && node.arms[1].kind !== 'else')
		throw new Error(
			`Svelte emitter has no lowering for a ${node.arms[1].kind} branch arm (${node.id})`,
		);
	const test = printExpression(expression(node.expression));
	const arm = (children: readonly TemplateNode[]): string =>
		inline
			? children.map((child) => renderNode(child, indent, true)).join('')
			: `\n${indent}\t${renderChildren(children, `${indent}\t`)}\n${indent}`;
	const elseArm = node.arms[1];
	const otherwise =
		elseArm && elseArm.children.length ? `{:else}${arm(elseArm.children)}` : '';
	return `{#if ${test}}${arm(node.arms[0]!.children)}${otherwise}{/if}`;
}

function renderKeyedRepeat(
	node: Extract<TemplateNode, { kind: 'keyed-repeat' }>,
	indent: string,
	inline: boolean,
): string {
	if (node.index)
		throw new Error(`Svelte keyed repeat ${node.id} has no lowering for an index binding`);
	if (node.empty.length)
		throw new Error(`Svelte keyed repeat ${node.id} has no lowering for an empty fallback`);
	if (node.row.length === 0) throw new Error(`Svelte keyed repeat ${node.id} has no row`);
	const collection = printExpression(expression(node.collection.expression));
	const key = printExpression(expression(node.key.expression));
	const row = inline
		? node.row.map((child) => renderNode(child, indent, true)).join('')
		: `\n${indent}\t${renderChildren(node.row, `${indent}\t`)}\n${indent}`;

			return;
		}
		if (seen.has(value)) return;
		seen.add(value);
		const node = value as Node;
		visit(node);
		for (const key of TEMPLATE_CHILD_KEYS) step(node[key]);
	};
	step(nodes);
}

// ---------------------------------------------------------------------------
// the two ASTs this gate reads
// ---------------------------------------------------------------------------

type Parsed = {
	/** The emitted module's TypeScript AST. */
	readonly module: Node;
	/** The exported component class. */
	readonly component: Node | null;
	/** The `@Component({...})` metadata object. */
	readonly metadata: Node | null;
	/** The INLINE template text, exactly as `ng build` would read it. */
	readonly template: string | null;
	/** 1-based source line the template literal opens on. */
	readonly templateLine: number;
	/** Angular's own parse of the inline template. */
	readonly templateNodes: readonly Node[];
	readonly templateErrors: readonly string[];
};

function lineOfTs(node: Node): number | null {
	const line = node.loc?.start?.line;
	return typeof line === 'number' ? line : null;
}

function lineOfTemplate(parsed: Parsed, node: Node): number | null {
	const line = node.sourceSpan?.start?.line;
	return typeof line === 'number' ? parsed.templateLine + line : null;
}

function decoratorNamed(node: Node, name: string): Node | undefined {
	return ((node.decorators ?? []) as Node[]).find(
		(decorator) =>
			decorator.expression?.type === 'CallExpression' &&
			decorator.expression.callee?.type === 'Identifier' &&
			decorator.expression.callee.name === name,
	);
}

function parseEmitted(file: string, source: string): Parsed | null {
	let module: Node;
	try {
		module = tsParser.parse(source, {
			loc: true,
			range: true,
			sourceType: 'module',
		}) as unknown as Node;
	} catch {
		return null;
	}
	let component: Node | null = null;
	walkTs(module, (node) => {
		if (node.type === 'ClassDeclaration' && decoratorNamed(node, 'Component')) component = node;
	});
	const decorator = component ? decoratorNamed(component, 'Component') : undefined;
	const metadata = (decorator?.expression?.arguments?.[0] as Node | undefined) ?? null;
	const templateProperty = ((metadata?.properties ?? []) as Node[]).find(
		(property) => property.type === 'Property' && property.key?.name === 'template',
	);
	const literal = templateProperty?.value as Node | undefined;
	const template =
		literal?.type === 'TemplateLiteral' && literal.quasis?.length === 1
			? String(literal.quasis[0].value?.cooked ?? '')
			: null;
	const parsedTemplate =
		template === null ? null : parseTemplate(template, file.replace(/\.ts$/, '.html'));
	return {
		module,
		component,
		metadata: metadata?.type === 'ObjectExpression' ? metadata : null,
		template,
		templateLine: literal ? (lineOfTs(literal) ?? 1) : 1,
		templateNodes: (parsedTemplate?.nodes ?? []) as Node[],
		templateErrors: (parsedTemplate?.errors ?? []).map((error) => String(error.msg ?? error)),
	};
}

// ---------------------------------------------------------------------------
// IR-7
// ---------------------------------------------------------------------------

/**
 * Methods whose whole purpose is to mutate their receiver. Deliberately NOT a
 * list of "calls" - `this.todos.filter(...)` inside a getter is correct and must
 * stay accepted, which is what stops this policy degenerating into "reject any
 * call".
 */
const KNOWN_MUTATING_METHODS = new Set([
	'add',
	'append',
	'appendChild',
	'assign',
	'clear',
	'copyWithin',
	'defineProperty',
	'delete',
	'fill',
	'insertBefore',
	'pop',
	'push',
	const found: ObservedForm[] = [];
	walkTs(parsed.module, (node) => {
		if (node.type === 'ImportDeclaration') {
			const from = String((node.source as Node | undefined)?.value ?? '?');
			const specifiers = (node.specifiers ?? []) as Node[];
			const line = lineOfTs(node);
			if (specifiers.length === 0) found.push({ kind: 'import', form: `${from}#*`, line });
			for (const specifier of specifiers)
				found.push({
					kind: 'import',
					form: `${from}#${
						specifier.type === 'ImportSpecifier'
							? String(specifier.imported?.name ?? '?')
							: specifier.type === 'ImportDefaultSpecifier'
								? 'default'
								: '*'
					}`,
					line,
				});
		}
		if (node.type === 'Decorator')
			found.push({
				kind: 'decorator',
				form: String(node.expression?.callee?.name ?? node.expression?.name ?? '?'),
				line: lineOfTs(node),
			});
	});
	for (const property of (parsed.metadata?.properties ?? []) as Node[])
		found.push({
			kind: 'component-metadata',
			form: String(property.key?.name ?? property.key?.value ?? '?'),
			line: lineOfTs(property),
		});
	if (parsed.metadata)
		found.push({ kind: 'component-metadata', form: '(no standalone key)', line: null });
	for (const clause of (parsed.component?.implements ?? []) as Node[])
		found.push({ kind: 'class-heritage', form: 'implements', line: lineOfTs(clause) });
	if (parsed.component?.superClass)
		found.push({ kind: 'class-heritage', form: 'extends', line: lineOfTs(parsed.component) });
	for (const member of (parsed.component?.body?.body ?? []) as Node[]) {
		const line = lineOfTs(member);
		if (member.type === 'PropertyDefinition')
			found.push({ kind: 'class-member', form: member.static ? 'static-property' : 'property', line });
		else if (member.type === 'MethodDefinition')
			found.push({
				kind: 'class-member',
				form: member.kind === 'method' ? 'method' : String(member.kind),
				line,
			});
		else found.push({ kind: 'class-member', form: String(member.type), line });
	}

	walkTemplate(parsed.templateNodes, (node) => {
		const name = templateNodeName(node);
		const line = lineOfTemplate(parsed, node);
		found.push({ kind: 'template-node', form: name, line });
		if (name === 'BoundText') found.push({ kind: 'template-binding', form: 'interpolation', line });
		if (name === 'BoundAttribute')
			found.push({ kind: 'template-binding', form: bindingTypeName(node.type), line });
		if (name === 'BoundEvent') found.push({ kind: 'template-binding', form: 'event', line });
		if (name === 'IfBlock') found.push({ kind: 'control-flow', form: '@if', line });
		if (name === 'IfBlockBranch' && node.expression === null)
			found.push({ kind: 'control-flow', form: '@else', line });
		if (name === 'ForLoopBlock') {
			found.push({ kind: 'control-flow', form: '@for', line });
			if (node.empty) found.push({ kind: 'control-flow', form: '@empty', line });
		}
	});
	return found;
}

/**
 * Every form the emitted source actually contains, deduped and sorted. Exported
 * because a fail-closed allowlist that observes NOTHING passes vacuously, and
 * `test/gate.test.ts` pins the observed set of the shipped corpus against a
 * literal - so a walk that stopped descending is a red test rather than a silently
 * green gate.
 */
export function collectEmittedForms(source: string): ReadonlyArray<{
