 */
function templateParseViolations(file: string, parsed: Parsed): GateViolation[] {
	if (parsed.template === null)
		return [
			violation(
				file,
				'template-parse',
				'Emitted Angular source has no inline `template:` template literal on its @Component decorator, so Angular\'s own parser has nothing to arbitrate',
				1,
			),
		];
	return parsed.templateErrors.map((message) =>
		violation(
			file,
			'template-parse',
			`@angular/compiler parseTemplate reported: ${message}`,
			parsed.templateLine,
		),
	);
}

async function sourceViolations(file: string, source: string): Promise<GateViolation[]> {
	const violations: GateViolation[] = [];
	if (!source.startsWith(GENERATED_HEADER))
		violations.push(
			violation(
				file,
				'generated-header',
				`Emitted Angular source must open with ${JSON.stringify(GENERATED_HEADER)}`,
				1,
			),
		);
	const parsed = parseEmitted(file, source);
	if (!parsed)
		return [
			...violations,
			violation(file, 'generated-header', 'TypeScript could not parse emitted source', 1),
		];
	if (!parsed.component)
		return [
			...violations,
			violation(
				file,
				'generated-header',
				'Emitted Angular source declares no class carrying an @Component decorator',
				1,
			),
		];
	violations.push(...templateParseViolations(file, parsed));
	violations.push(...inventoryViolations(file, parsed));
	violations.push(...whitespaceViolations(file, parsed));
	violations.push(...signalViolations(file, parsed));
	violations.push(...twoWayViolations(file, parsed));
	violations.push(...outputViolations(file, parsed));
	violations.push(...changeDetectionViolations(file, parsed));
	violations.push(...stopPropagationViolations(file, parsed));
	violations.push(...getterViolations(file, parsed));
	return violations;
}

